def parse_args():
    parser = argparse.ArgumentParser(
        description='Cache the prompt embeddings of every dataset in a config, encoding each distinct prompt '
                    'once into a file named by its hash. A dataset with a prompt_cache_dir lists its records\' '
                    'files by record key in a datalist that datasets may share; an ImagePrompt lists them in '
                    'dataset order in its cache_dir datalist. Usage: '
                    'torchrun --nnodes=1 --nproc_per_node=<NUM_GPUS> tools/datasets/cache_prompt_embeds.py '
                    '<PATH_TO_CONFIG> --launcher pytorch')
    parser.add_argument('config', help='file path to the config containing the datasets and text encoder')
    parser.add_argument('--text-encoder', type=str, help='file path to the config of text encoder')
    parser.add_argument(
        '--launcher',
        choices=['none', 'pytorch', 'slurm', 'mpi'],
        default='none',
        help='job launcher')
    parser.add_argument(
        '--data',
        type=str,
        nargs='+')
    parser.add_argument(
        '--batch-size', type=int, default=8, help='batch size per GPU')
    parser.add_argument(
        '--workers', type=int, default=4, help='number of prompt reading workers per GPU')
    parser.add_argument('--local-rank', '--local_rank', type=int, default=0)
    args = parser.parse_args()
    if 'LOCAL_RANK' not in os.environ:
        os.environ['LOCAL_RANK'] = str(args.local_rank)

    return args


def to_scaled_fp8(t: torch.Tensor, dtype: torch.dtype = torch.float8_e4m3fn, eps=1e-6):
    amax = t.abs().max()
    fp8_max = torch.finfo(dtype).max
    scale = (amax.float() / fp8_max).clamp(min=eps)
    t_scaled = (t.float() / scale).to(dtype)
    return t_scaled, scale


class Preprocessor(nn.Module):

    def __init__(self, text_encoder):
        super().__init__()
        self.text_encoder = build_module(text_encoder)

    def val_step(self, data, **kwargs):
        prompt_embed_kwargs = self.text_encoder(**data['prompt_kwargs'])
        return dict(
            data_ids=data['ids'],
            prompts=data['name'],
            prompt_embed_kwargs=prompt_embed_kwargs)


def save_cache(data, cache_path):
    file_client = FileClient.infer_client(uri=cache_path)
    bytesio = BytesIO()
    compressor = zstd.ZstdCompressor(level=3)
    with compressor.stream_writer(bytesio, closefd=False) as f:
        pickle.dump(data, f)
    file_client.put(bytesio.getvalue(), cache_path)


def prompt_cache_name(prompt_kwargs):
    """The cache file name of one text-encoder input: a hash of the prompt alone when it is the only
    keyword, else of all keywords."""
    key = (prompt_kwargs['prompt'] if prompt_kwargs.keys() == {'prompt'}
           else orjson.dumps(prompt_kwargs, option=orjson.OPT_SORT_KEYS).decode('utf-8'))
    return hashlib.sha256(key.encode('utf-8')).hexdigest()


def read_prompt_kwargs(dataset, cfg, args, rank, world_size):
    """The prompt_kwargs of every sample in dataset order, gathered to rank 0 (None on the other ranks)."""
    # The default loader config
    loader_cfg = dict(shuffle=False)
    # The overall dataloader settings
    loader_cfg.update({
        k: v
        for k, v in cfg.data.items()
        if k not in [
            'train_dataloader', 'val_dataloader', 'test_dataloader'
        ] and not re.fullmatch(r'(train|val|test)\d*', k)
    })

    # specific config for test loader
    test_loader_cfg = {**loader_cfg, **cfg.data.get('test_dataloader', {})}
    test_loader_cfg.update(
        samples_per_gpu=args.batch_size,
        workers_per_gpu=args.workers,
        prefetch_factor=args.batch_size * 2)

    dataloader = build_dataloader(dataset, **test_loader_cfg)
    # the distributed samplers pad by repeating samples, so key the prompt_kwargs by sample id
    prompt_kwargs = dict()
    for data in dataloader:
        for batch_id, data_id in enumerate(data['ids'].data[0]):
            prompt_kwargs[data_id] = {k: v.data[0][batch_id] for k, v in data['prompt_kwargs'].items()}
    if world_size > 1:
        gathered = [None] * world_size if rank == 0 else None
        dist.gather_object(prompt_kwargs, gathered, dst=0)
        prompt_kwargs = {k: v for part in gathered for k, v in part.items()} if rank == 0 else None
    return [prompt_kwargs[i] for i in range(len(dataset))] if rank == 0 else None


def read_datalist(datalist_path):
    datalist_bytesio = BytesIO(FileClient.infer_client(uri=datalist_path).get(datalist_path))
    if datalist_path.endswith('.jsonl.gz'):
        with gzip.open(datalist_bytesio, 'rt', encoding='utf-8') as f:
            datalist = f.readlines()
    else:
        datalist = datalist_bytesio.read().decode('utf-8').splitlines()
    return [orjson.loads(line) for line in datalist]


def write_datalist(entries, datalist_path):
    bytesio = BytesIO()
    datalist = ''.join(orjson.dumps(entry).decode('utf-8') + '\n' for entry in entries)
    datalist = datalist.encode('utf-8')
    if datalist_path.endswith('.jsonl.gz'):
        with gzip.GzipFile(fileobj=bytesio, mode='wb') as f:
            f.write(datalist)
    elif datalist_path.endswith('.jsonl'):
        bytesio.write(datalist)
    else:
        raise ValueError('Datalist file must be .jsonl or .jsonl.gz')
    FileClient.infer_client(uri=datalist_path).put(bytesio.getvalue(), datalist_path)


def main():
    args = parse_args()

    cfg = Config.fromfile(args.config)
    if args.text_encoder is not None:
        cfg.model.text_encoder = Config.fromfile(args.text_encoder).model.text_encoder
    assert hasattr(cfg.model, 'text_encoder')

    setup_multi_processes(cfg)

    # import modules from string list.
    if cfg.get('custom_imports', None):
        from mmcv.utils import import_modules_from_strings
        import_modules_from_strings(**cfg['custom_imports'])
    setup_global_config(dict(cfg.get('global_config', dict())))

    # init distributed env first, since logger depends on the dist info.
    if args.launcher == 'none':
        distributed = False
        rank = 0
        world_size = 1
    else:
        distributed = True
        init_dist(args.launcher, **cfg.dist_params)
        rank, world_size = get_dist_info()
    local_world_size = os.environ.get('LOCAL_WORLD_SIZE', 1)
    num_cpus = mp.cpu_count() // int(local_world_size)
    max_save_cache_workers = max(num_cpus - 2, 1)

    logger = get_root_logger(log_level=cfg.log_level)

    if args.data is None:
        data_dict = {k: v for k, v in cfg.data.items() if re.fullmatch(r'(train|val|test)\d*', k)}
    else:
        data_dict = {k: cfg.data[k] for k in args.data}

    # Each dataset writes one of two kinds of cache, collected on rank 0 by (cache dir path, datalist path):
    # - a prompt cache, for a dataset with a prompt_cache_dir (e.g. VideoAudioPrompt): its datalist maps each
    #   record key to the files of the record's prompts, and any dataset or config may share it
    # - an ImagePrompt cache, for an ImagePrompt with a cache_dir: its datalist lists one file per sample, in
    #   dataset order
    prompt_caches = dict()  # -> {record key: file names of the record's prompts}
    image_prompt_caches = dict()  # -> [file name of each sample]
    prompt_kwargs = dict()  # file name -> prompt_kwargs of one prompt
    for dataset_name, data_cfg in data_dict.items():
        for dataset in (data_cfg['datasets'] if data_cfg['type'] == 'ConcatDataset' else [data_cfg]):
            dataset = dataset.copy()
            use_prompt_cache = 'prompt_cache_dir' in dataset
            cache_dir, datalist_path = (
                (dataset.pop('prompt_cache_dir'), dataset.pop('prompt_cache_datalist_path', None)) if use_prompt_cache
                else (dataset.get('cache_dir'), dataset.get('cache_datalist_path')))
            if cache_dir is None or datalist_path is None:
                logger.info(f'Skipping a {dataset_name} dataset without a prompt cache.')
                continue
            # build without the caches being written, and without repeat, which only duplicates indices
            for k in ('cache_dir', 'cache_datalist_path', 'repeat'):
                dataset.pop(k, None)
            if use_prompt_cache:
                dataset.update(load_videos=False)
            data_root = dataset['data_root']
            dataset = build_dataset(dataset)
            if len(dataset) == 0:
                continue
            dataset_prompt_kwargs = read_prompt_kwargs(dataset, cfg, args, rank, world_size)
            if rank != 0:
                continue

            names = []
            for sample_prompt_kwargs in dataset_prompt_kwargs:
                # a dataset in all-prompts mode hands over every prompt of a record, in record order
                prompts = sample_prompt_kwargs['prompt']
                if isinstance(prompts, list):
                    record_prompt_kwargs = [{**sample_prompt_kwargs, 'prompt': prompt} for prompt in prompts]
                else:
                    record_prompt_kwargs = [sample_prompt_kwargs]
                record_names = [prompt_cache_name(kwargs) for kwargs in record_prompt_kwargs]
                prompt_kwargs.update(zip(record_names, record_prompt_kwargs))
                names.append(record_names)

            key = (FileClient.infer_client(uri=data_root).join_path(data_root, cache_dir), datalist_path)
            if use_prompt_cache:  # sample i is record start_ind + i, since repeat is disabled
                records = prompt_caches.setdefault(key, dict())
                for i, record_names in enumerate(names):
                    records[dataset.get_record_key(dataset.start_ind + i)] = record_names
            else:
                assert key not in image_prompt_caches, f'Datalist {datalist_path} is used by more than one dataset.'
                assert all(len(record_names) == 1 for record_names in names), \
                    'An ImagePrompt cache holds one prompt per sample.'
                image_prompt_caches[key] = [record_names[0] for record_names in names]

    # content-addressed files: any existing file is complete, whichever config wrote it
    if rank == 0:
        cache_names = []  # (cache dir path, file names to cache there)
        for (cache_dir_path, _), records in prompt_caches.items():
            cache_names.append((cache_dir_path, [name for record_names in records.values() for name in record_names]))
        for (cache_dir_path, _), names in image_prompt_caches.items():
            cache_names.append((cache_dir_path, names))

        todo = []
        for cache_dir_path, names in cache_names:
            file_client = FileClient.infer_client(uri=cache_dir_path)
            existing = set(os.path.splitext(path)[0] for path in file_client.list_dir_or_file(cache_dir_path)
                           if path.endswith('.zst')) if file_client.isdir(cache_dir_path) else set()
            missing = sorted(set(names) - existing)
            logger.info(f'{cache_dir_path}: {len(set(names))} distinct prompts, {len(missing)} to be cached.')
            todo.extend((cache_dir_path, name, prompt_kwargs[name]) for name in missing)
        # similar lengths share a batch, so little padding is encoded
        todo.sort(key=lambda item: (len(item[2]['prompt']), item[:2]))
        todo = [todo[r::world_size] for r in range(world_size)]
    if distributed:
        _todo = [None]
        dist.scatter_object_list(_todo, todo if rank == 0 else None, src=0)
        todo = _todo[0]
    else:
        todo = todo[0]

    torch.set_grad_enabled(False)

    if len(todo) > 0:
        model = Preprocessor(cfg.model.text_encoder).requires_grad_(False).eval()

        if distributed:  # every rank holds the whole text encoder, so ranks may run different numbers of batches
            model = apply_module_wrapper(model, 'ddp', cfg)
        else:
            model = MMDataParallel(model, device_ids=[0])

    mp_ctx = mp.get_context("spawn")
    proc_pool = ProcessPoolExecutor(
        max_workers=min(max_save_cache_workers, args.batch_size * 2),
        mp_context=mp_ctx)
    cap = max_save_cache_workers * 2
    pending = set()

    pbar = tqdm(total=len(todo) * world_size, desc='Caching prompt embeddings', unit='prompt', disable=rank != 0)
    for i in range(0, len(todo), args.batch_size):
        batch = todo[i:i + args.batch_size]
        data = collate([
            dict(
                ids=DC(batch_id, cpu_only=True),
                name=DC(kwargs['prompt'], cpu_only=True),
                prompt_kwargs={k: DC(v, cpu_only=True) for k, v in kwargs.items()})
            for batch_id, (_, _, kwargs) in enumerate(batch)], samples_per_gpu=len(batch))
        outputs_dict = model.val_step(data)

        for batch_id, (cache_dir_path, name, kwargs) in enumerate(batch):
            cached_data = dict(
                prompt=kwargs['prompt'],
                prompt_embed_kwargs=dict())
            for k, v in outputs_dict['prompt_embed_kwargs'].items():
                if k in ('encoder_hidden_states', 'cap_feats'):
                    value_fp8, value_scale = to_scaled_fp8(v[batch_id])
                    cached_data['prompt_embed_kwargs'][k] = value_fp8.cpu()
                    cached_data['prompt_embed_kwargs'][k + '_scale'] = value_scale.cpu()
                else:
                    cached_data['prompt_embed_kwargs'][k] = v[batch_id].cpu().clone()

            if len(pending) >= cap:
                done, pending = wait(pending, return_when=FIRST_COMPLETED)
                for f in done:
                    f.result()

            pending.add(proc_pool.submit(
                save_cache,
                cached_data,
                FileClient.infer_client(uri=cache_dir_path).join_path(cache_dir_path, name + '.zst')))
        pbar.update(len(batch) * world_size)

    if pending:
        done, pending = wait(pending)
        for f in done:
            f.result()
    proc_pool.shutdown(wait=True)

    if world_size > 1:
        dist.barrier()

    if rank == 0:
        for (_, datalist_path), records in prompt_caches.items():
            entries = []
            if FileClient.infer_client(uri=datalist_path).isfile(datalist_path):  # keep other configs' records
                entries = read_datalist(datalist_path)
            if entries and 'filename' in entries[0]:
                # Keep the format and sample order for ImagePrompt readers sharing this cache.
                assert all(filenames == [record_key] for record_key, filenames in records.items()), \
                    'An ImagePrompt datalist can only be shared with prompt-only sources.'
                existing_names = {entry['filename'] for entry in entries}
                entries.extend(dict(filename=record_key) for record_key in records if record_key not in existing_names)
            else:
                records = {**{entry['record_key']: entry['filenames'] for entry in entries}, **records}
                entries = [dict(record_key=record_key, filenames=filenames)
                           for record_key, filenames in records.items()]
            write_datalist(entries, datalist_path)
            logger.info(f'Wrote datalist to {datalist_path}')
        for (_, datalist_path), names in image_prompt_caches.items():
            write_datalist([dict(filename=name) for name in names], datalist_path)
            logger.info(f'Wrote datalist to {datalist_path}')

    if world_size > 1:
        dist.barrier()

    return


if __name__ == '__main__':
    main()
